css:
.hqr-page { page-break-after: always; display: flex; flex-wrap: wrap; align-content: flex-start; }
.hqr-page:last-child { page-break-after: auto; }
.hqr-bcard {
    box-sizing: border-box;
    width: 50%; height: 67mm;
    padding: 4mm;
    border: 0.3mm solid #999;
    display: flex; flex-direction: column; align-items: center; justify-content: center;
    page-break-inside: avoid; break-inside: avoid;
}
.hqr-bqr { width: 40mm; height: 40mm; }
.hqr-bid { margin-top: 2.5mm; font-size: 13pt; font-weight: 800; letter-spacing: 0.5pt; font-family: 'Courier New', monospace; }

html:
{% set _pp = 8 %}
<div class="hqr-wrap">
{%- for row in doc.labels %}
    {%- if loop.index0 % _pp == 0 %}<div class="hqr-page">{% endif %}
        <div class="hqr-bcard">
            {% if row.qr_code_image %}<img class="hqr-bqr" src="{{ row.qr_code_image }}">{% endif %}
            <div class="hqr-bid">{{ row.harvester_id }}</div>
        </div>
    {%- if loop.index % _pp == 0 or loop.last %}</div>{% endif %}
{%- endfor %}
</div>
